package com.nextrade.engine.market; import java.util.*; public final class MarketDataBuffer {private final int capacity;private final ArrayDeque<MarketTick> ticks=new ArrayDeque<>();public MarketDataBuffer(int capacity){if(capacity<1)throw new IllegalArgumentException("capacity");this.capacity=capacity;}public synchronized void add(MarketTick t){if(ticks.size()==capacity)ticks.removeFirst();ticks.addLast(t);}public synchronized List<MarketTick> snapshot(){return List.copyOf(ticks);}public synchronized Optional<MarketTick> latest(){return Optional.ofNullable(ticks.peekLast());}}
